#include <iostream>

class DT {
private:
    int n;
    double *a;
public:
    DT() : n(0), a(nullptr) {}
    explicit DT(int deg) : n(deg), a(new double[deg + 1]()) {}

    // Deep copy constructor
    DT(const DT &d) : n(d.n), a(nullptr) {
        if (d.a != nullptr) {
            a = new double[n + 1];
            for (int i = 0; i <= n; ++i) {
                a[i] = d.a[i];
            }
        }
    }

    ~DT() {
        delete[] a;
        a = nullptr;
        n = 0;
    }

    friend std::ostream& operator<<(std::ostream &os, const DT &d) {
        os << "Cac he so (tu a0): ";
        if (d.a != nullptr) {
            for (int i = 0; i <= d.n; ++i) {
                os << d.a[i] << (i == d.n ? "" : " ");
            }
        }
        return os;
    }

    friend std::istream& operator>>(std::istream &is, DT &d) {
        delete[] d.a;
        d.a = nullptr;
        if (is >> d.n) {
            d.a = new double[d.n + 1];
            for (int i = 0; i <= d.n; ++i) {
                is >> d.a[i];
            }
        }
        return is;
    }
};

int main() {
    DT d;
    if (std::cin >> d) {
        DT u(d); // Deep copy
        std::cout << "d: " << d << "\n";
        std::cout << "u: " << u << "\n";
        // Read another polynomial into d to prove u remains unchanged
        if (std::cin >> d) {
            std::cout << "After updating d:\n";
            std::cout << "d: " << d << "\n";
            std::cout << "u: " << u << "\n";
        }
    }
    return 0;
}

#include <iostream>

class ResourceTracker {
private:
    int id;
    int *data;
public:
    ResourceTracker(int trackerId, int val) : id(trackerId), data(new int(val)) {
        std::cout << "Constructed tracker " << id << " with val = " << *data << "\n";
    }

    ~ResourceTracker() {
        std::cout << "Destructing tracker " << id << " and freeing memory\n";
        delete data;
        data = nullptr;
    }

    int getValue() const {
        return (data != nullptr) ? *data : 0;
    }
};

int main() {
    std::cout << "Entering main scope\n";
    ResourceTracker globalLike(1, 100);
    {
        std::cout << "Entering inner scope\n";
        ResourceTracker local(2, 200);
        std::cout << "Inside inner scope: val = " << local.getValue() << "\n";
        std::cout << "Exiting inner scope\n";
    }
    std::cout << "Back in main scope: val = " << globalLike.getValue() << "\n";
    std::cout << "Exiting main scope\n";
    return 0;
}
